const SB_KEY = $env.SB_KEY;
const RESEND_KEY = $env.RESEND_KEY;
const body = $input.first().json.body;

if (body.type !== 'package_shipped') return [];

const info = body.data.shipment;
const pf_order_id = body.data.order.id;
const sbh = { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json' };

const dbRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?printful_order_id=eq.${pf_order_id}&select=*`,
  headers: sbh, json: true
});
if (!dbRes || dbRes.length === 0) throw new Error('Order not found in Supabase');
const cloth = dbRes[0];

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${cloth.id}`,
  headers: sbh, json: true,
  body: { status: 'shipped', tracking_number: info.tracking_number, tracking_url: info.tracking_url }
});

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.resend.com/emails',
  headers: { Authorization: `Bearer ${RESEND_KEY}`, 'Content-Type': 'application/json' },
  json: true,
  body: {
    from: 'TOTEHM <totehm@higher.boutique>',
    to: [cloth.email],
    subject: 'Your TOTEHM Cloth is on its way.',
    html: `<p>Your physical garment has been encoded and shipped.</p><p>Track its arrival here: <a href="${info.tracking_url}">${info.tracking_number}</a></p><p>— TOTEHM</p>`
  }
});

return [{ json: { ok: true, cloth_id: cloth.id } }];

return [{ json: {
  ...$input.first().json,
  SB_KEY: process.env.SB_KEY,
  RESEND_KEY: process.env.RESEND_KEY
}}];
